import { CreateOrderInput, OrderDto } from "./dtos";
import { DomainError, InsufficientStockError, NotFoundError } from "../domain/errors";
import { Order, OrderLine, OrderState } from "../domain/order";
import { OrderRepository, ProductRepository } from "../domain/repositories";

export class OrderService {
  private nextId = 1;

  public constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
  ) {}

  public placeOrder(input: CreateOrderInput): OrderDto {
    if (!input.customerId) throw new DomainError("An order requires a customer");
    const lines = this.normaliseLines(input.items);
    const reservedProducts = lines.map((line) => ({ line, product: this.requireProduct(line.productId) }));
    reservedProducts.forEach(({ line, product }) => {
      if (!product.canReserve(line.quantity)) throw new InsufficientStockError(product.id);
    });
    reservedProducts.forEach(({ line, product }) => product.reserve(line.quantity));
    const order = new Order(`order-${this.nextId++}`, input.customerId, lines);
    reservedProducts.forEach(({ product }) => this.products.save(product));
    this.orders.save(order);
    return this.toDto(order);
  }

  public advanceOrder(id: string, state: Exclude<OrderState, "placed" | "cancelled">): OrderDto {
    const order = this.requireOrder(id);
    order.advanceTo(state);
    this.orders.save(order);
    return this.toDto(order);
  }

  public cancelOrder(id: string): OrderDto {
    const order = this.requireOrder(id);
    order.cancel();
    order.lines.forEach((line) => {
      const product = this.requireProduct(line.productId);
      product.release(line.quantity);
      this.products.save(product);
    });
    this.orders.save(order);
    return this.toDto(order);
  }

  public listOrders(state?: OrderState): OrderDto[] {
    return this.orders.listByState(state).map((order) => this.toDto(order));
  }

  private normaliseLines(items: CreateOrderInput["items"]): OrderLine[] {
    const quantities = new Map<string, number>();
    items.forEach(({ productId, quantity }) => {
      if (!productId || !Number.isInteger(quantity) || quantity <= 0) {
        throw new DomainError("Each order item needs a product id and positive integer quantity");
      }
      quantities.set(productId, (quantities.get(productId) ?? 0) + quantity);
    });
    return [...quantities].map(([productId, quantity]) => ({ productId, quantity }));
  }

  private requireOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new NotFoundError("Order");
    return order;
  }

  private requireProduct(id: string) {
    const product = this.products.findById(id);
    if (!product) throw new NotFoundError("Product");
    return product;
  }

  private toDto(order: Order): OrderDto {
    return { id: order.id, customerId: order.customerId, state: order.state, items: order.lines };
  }
}

